[metadata] {"type": "create", "filePath": "/app/output/final_report.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Chocolate Retail Sales Performance Report (2023–2024)</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>
<style>
  :root {
    --brown-deep: #3B1A08;
    --brown-mid: #6B3A2A;
    --brown-warm: #8B5E3C;
    --gold: #C8942A;
    --gold-light: #E8B84B;
    --cream: #FAF6F0;
    --cream-mid: #F0E8DA;
    --text-primary: #1A0F08;
    --text-secondary: #5A3E2B;
    --text-muted: #8B7060;
    --green-pos: #2D7D46;
    --red-neg: #B53A2A;
    --border: #DDD0C0;
    --white: #FFFFFF;
    --shadow: 0 2px 12px rgba(59,26,8,0.08);
    --shadow-lg: 0 4px 24px rgba(59,26,8,0.12);
  }

  * { box-sizing: border-box; margin: 0; padding: 0; }

  body {
    font-family: 'Georgia', 'Times New Roman', serif;
    background: var(--cream);
    color: var(--text-primary);
    line-height: 1.6;
    font-size: 15px;
  }

  /* HEADER */
  .report-header {
    background: linear-gradient(135deg, var(--brown-deep) 0%, var(--brown-mid) 60%, var(--brown-warm) 100%);
    color: var(--white);
    padding: 56px 64px 48px;
    position: relative;
    overflow: hidden;
  }
  .report-header::before {
    content: '';
    position: absolute;
    top: -40px; right: -40px;
    width: 300px; height: 300px;
    background: radial-gradient(circle, rgba(200,148,42,0.15) 0%, transparent 70%);
    border-radius: 50%;
  }
  .report-header::after {
    content: '';
    position: absolute;
    bottom: -60px; left: 30%;
    width: 200px; height: 200px;
    background: radial-gradient(circle, rgba(200,148,42,0.10) 0%, transparent 70%);
    border-radius: 50%;
  }
  .header-label {
    font-family: 'Arial', sans-serif;
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 3px;
    text-transform: uppercase;
    color: var(--gold-light);
    margin-bottom: 12px;
    opacity: 0.9;
  }
  .report-title {
    font-size: 36px;
    font-weight: normal;
    line-height: 1.2;
    margin-bottom: 10px;
    color: var(--white);
  }
  .report-subtitle {
    font-size: 16px;
    color: rgba(255,255,255,0.75);
    font-style: italic;
    margin-bottom: 32px;
  }
  .header-meta {
    display: flex;
    gap: 40px;
    font-family: 'Arial', sans-serif;
    font-size: 12px;
    color: rgba(255,255,255,0.65);
  }
  .header-meta span strong {
    display: block;
    color: var(--gold-light);
    font-size: 11px;
    letter-spacing: 1px;
    text-transform: uppercase;
    margin-bottom: 2px;
  }

  /* NAV */
  .report-nav {
    background: var(--brown-deep);
    padding: 0 64px;
    position: sticky;
    top: 0;
    z-index: 100;
    border-bottom: 2px solid var(--gold);
  }
  .report-nav ul {
    display: flex;
    list-style: none;
    gap: 0;
    overflow-x: auto;
  }
  .report-nav ul li a {
    display: block;
    padding: 14px 18px;
    font-family: 'Arial', sans-serif;
    font-size: 12px;
    font-weight: 600;
    letter-spacing: 0.5px;
    color: rgba(255,255,255,0.65);
    text-decoration: none;
    white-space: nowrap;
    border-bottom: 3px solid transparent;
    transition: all 0.2s;
  }
  .report-nav ul li a:hover {
    color: var(--gold-light);
    border-bottom-color: var(--gold);
  }

  /* MAIN LAYOUT */
  .report-body {
    max-width: 1280px;
    margin: 0 auto;
    padding: 48px 64px 80px;
  }

  /* SECTIONS */
  .section {
    margin-bottom: 64px;
  }
  .section-header {
    display: flex;
    align-items: center;
    gap: 16px;
    margin-bottom: 32px;
    padding-bottom: 16px;
    border-bottom: 2px solid var(--cream-mid);
  }
  .section-number {
    width: 36px; height: 36px;
    background: var(--gold);
    color: var(--white);
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-family: 'Arial', sans-serif;
    font-weight: 700;
    font-size: 14px;
    flex-shrink: 0;
  }
  .section-title {
    font-size: 22px;
    color: var(--brown-deep);
    font-weight: normal;
  }

  /* KPI CARDS */
  .kpi-grid {
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 16px;
    margin-bottom: 40px;
  }
  .kpi-card {
    background: var(--white);
    border-radius: 12px;
    padding: 24px 20px;
    box-shadow: var(--shadow);
    border-top: 4px solid var(--gold);
    position: relative;
    overflow: hidden;
  }
  .kpi-card::after {
    content: '';
    position: absolute;
    bottom: -20px; right: -20px;
    width: 80px; height: 80px;
    background: var(--cream-mid);
    border-radius: 50%;
    opacity: 0.5;
  }
  .kpi-label {
    font-family: 'Arial', sans-serif;
    font-size: 10px;
    font-weight: 700;
    letter-spacing: 1.5px;
    text-transform: uppercase;
    color: var(--text-muted);
    margin-bottom: 8px;
  }
  .kpi-value {
    font-size: 26px;
    font-weight: bold;
    color: var(--brown-deep);
    line-height: 1;
    margin-bottom: 6px;
  }
  .kpi-value.large { font-size: 22px; }
  .kpi-badge {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    font-family: 'Arial', sans-serif;
    font-size: 11px;
    font-weight: 600;
    padding: 2px 8px;
    border-radius: 12px;
    background: #E8F5ED;
    color: var(--green-pos);
  }
  .kpi-badge.neutral { background: #F0EADF; color: var(--brown-warm); }
  .kpi-sub {
    font-family: 'Arial', sans-serif;
    font-size: 11px;
    color: var(--text-muted);
    margin-top: 4px;
  }

  /* INSIGHT BOX */
  .insight-box {
    background: linear-gradient(135deg, #FFF8ED 0%, #FFF3E0 100%);
    border-left: 4px solid var(--gold);
    border-radius: 0 8px 8px 0;
    padding: 20px 24px;
    margin-bottom: 24px;
  }
  .insight-box h4 {
    font-family: 'Arial', sans-serif;
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 1.5px;
    text-transform: uppercase;
    color: var(--gold);
    margin-bottom: 8px;
  }
  .insight-box p {
    font-size: 14px;
    color: var(--text-secondary);
    line-height: 1.7;
  }
  .insight-box ul {
    list-style: none;
    padding: 0;
  }
  .insight-box ul li {
    font-size: 14px;
    color: var(--text-secondary);
    padding: 4px 0;
    padding-left: 16px;
    position: relative;
  }
  .insight-box ul li::before {
    content: '▸';
    position: absolute;
    left: 0;
    color: var(--gold);
    font-size: 12px;
  }

  /* CHARTS */
  .chart-card {
    background: var(--white);
    border-radius: 12px;
    padding: 28px 32px;
    box-shadow: var(--shadow);
    margin-bottom: 24px;
  }
  .chart-title {
    font-family: 'Arial', sans-serif;
    font-size: 13px;
    font-weight: 700;
    color: var(--text-secondary);
    text-transform: uppercase;
    letter-spacing: 0.8px;
    margin-bottom: 6px;
  }
  .chart-subtitle {
    font-family: 'Arial', sans-serif;
    font-size: 12px;
    color: var(--text-muted);
    margin-bottom: 24px;
  }
  .chart-container {
    position: relative;
    width: 100%;
  }

  .charts-2col {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 24px;
  }
  .charts-3col {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 24px;
  }

  /* TABLE */
  .data-table-wrap {
    background: var(--white);
    border-radius: 12px;
    box-shadow: var(--shadow);
    overflow: hidden;
    margin-bottom: 24px;
  }
  .table-header {
    padding: 20px 24px;
    border-bottom: 1px solid var(--border);
  }
  .table-title {
    font-family: 'Arial', sans-serif;
    font-size: 13px;
    font-weight: 700;
    color: var(--text-secondary);
    text-transform: uppercase;
    letter-spacing: 0.8px;
  }
  .table-subtitle {
    font-family: 'Arial', sans-serif;
    font-size: 12px;
    color: var(--text-muted);
    margin-top: 4px;
  }
  table {
    width: 100%;
    border-collapse: collapse;
    font-family: 'Arial', sans-serif;
    font-size: 13px;
  }
  thead th {
    background: var(--cream);
    padding: 10px 16px;
    text-align: left;
    font-weight: 700;
    font-size: 11px;
    letter-spacing: 0.8px;
    text-transform: uppercase;
    color: var(--text-muted);
    border-bottom: 1px solid var(--border);
  }
  thead th.right { text-align: right; }
  tbody tr {
    border-bottom: 1px solid var(--cream-mid);
    transition: background 0.15s;
  }
  tbody tr:hover { background: var(--cream); }
  tbody tr:last-child { border-bottom: none; }
  td {
    padding: 10px 16px;
    color: var(--text-primary);
  }
  td.right { text-align: right; }
  td.mono {
    font-family: 'Courier New', monospace;
    font-size: 12px;
  }
  .rank-cell {
    font-weight: 700;
    color: var(--text-muted);
    width: 36px;
  }
  .bar-cell { width: 120px; }
  .mini-bar {
    height: 6px;
    background: var(--gold);
    border-radius: 3px;
    opacity: 0.75;
  }
  .badge-pill {
    display: inline-block;
    padding: 2px 10px;
    border-radius: 12px;
    font-size: 11px;
    font-weight: 600;
  }
  .pill-green { background: #E8F5ED; color: var(--green-pos); }
  .pill-amber { background: #FFF3DC; color: #9B6C00; }
  .pill-red   { background: #FDE8E5; color: var(--red-neg); }

  /* EXEC SUMMARY CALLOUTS */
  .summary-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
    margin-bottom: 24px;
  }
  .summary-card {
    background: var(--white);
    border-radius: 12px;
    padding: 24px;
    box-shadow: var(--shadow);
  }
  .summary-card h3 {
    font-size: 15px;
    color: var(--brown-mid);
    margin-bottom: 12px;
    padding-bottom: 8px;
    border-bottom: 1px solid var(--cream-mid);
  }
  .summary-card ul {
    list-style: none;
    padding: 0;
  }
  .summary-card ul li {
    font-size: 13px;
    color: var(--text-secondary);
    padding: 5px 0;
    padding-left: 18px;
    position: relative;
    font-family: 'Arial', sans-serif;
    line-height: 1.5;
  }
  .summary-card ul li::before {
    content: '•';
    position: absolute;
    left: 0;
    color: var(--gold);
    font-size: 16px;
    line-height: 1.2;
  }

  /* FOOTER */
  .report-footer {
    background: var(--brown-deep);
    color: rgba(255,255,255,0.5);
    text-align: center;
    padding: 24px 64px;
    font-family: 'Arial', sans-serif;
    font-size: 11px;
    letter-spacing: 0.5px;
  }
  .report-footer strong { color: var(--gold-light); }

  /* YoY comparison strip */
  .yoy-strip {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 16px;
    margin-bottom: 32px;
  }
  .yoy-card {
    background: var(--white);
    border-radius: 10px;
    padding: 20px;
    box-shadow: var(--shadow);
    display: flex;
    flex-direction: column;
    gap: 6px;
  }
  .yoy-label {
    font-family: 'Arial', sans-serif;
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 1px;
    text-transform: uppercase;
    color: var(--text-muted);
  }
  .yoy-values {
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
    gap: 8px;
  }
  .yoy-year {
    font-family: 'Arial', sans-serif;
  }
  .yoy-year span {
    display: block;
    font-size: 10px;
    color: var(--text-muted);
    margin-bottom: 2px;
  }
  .yoy-year strong {
    font-size: 18px;
    color: var(--brown-deep);
  }
  .yoy-change {
    font-family: 'Arial', sans-serif;
    font-size: 13px;
    font-weight: 700;
    color: var(--green-pos);
    background: #E8F5ED;
    padding: 3px 10px;
    border-radius: 20px;
  }

  @media (max-width: 900px) {
    .kpi-grid { grid-template-columns: repeat(2, 1fr); }
    .charts-2col { grid-template-columns: 1fr; }
    .report-body { padding: 32px 24px; }
    .report-header { padding: 40px 24px 32px; }
    .report-nav { padding: 0 24px; }
    .yoy-strip { grid-template-columns: 1fr; }
  }
</style>
</head>
<body>

<!-- HEADER -->
<header class="report-header">
  <div class="header-label">Management Report · Retail Analytics Division</div>
  <h1 class="report-title">Chocolate Retail Sales Performance Report</h1>
  <p class="report-subtitle">A comprehensive two-year analysis of transactions, products, stores, and customer behaviour</p>
  <div class="header-meta">
    <div><span><strong>Reporting Period</strong>January 2023 – December 2024</span></div>
    <div><span><strong>Dataset</strong>50,000 Transactions · 100 Stores · 202 Products</span></div>
    <div><span><strong>Prepared For</strong>Retail Management Leadership</span></div>
    <div><span><strong>Published</strong>April 2026</span></div>
  </div>
</header>

<!-- NAV -->
<nav class="report-nav">
  <ul>
    <li><a href="#exec-summary">Executive Summary</a></li>
    <li><a href="#sales-trends">Sales Trends</a></li>
    <li><a href="#product-performance">Products & Categories</a></li>
    <li><a href="#store-analysis">Store & Geographic</a></li>
    <li><a href="#discount-profitability">Discount & Profitability</a></li>
    <li><a href="#customer-insights">Customer Insights</a></li>
  </ul>
</nav>

<!-- MAIN -->
<main class="report-body">

  <!-- ═══ 1. EXECUTIVE SUMMARY ═══ -->
  <section class="section" id="exec-summary">
    <div class="section-header">
      <div class="section-number">1</div>
      <h2 class="section-title">Executive Summary</h2>
    </div>

    <!-- KPI Cards -->
    <div class="kpi-grid">
      <div class="kpi-card">
        <div class="kpi-label">Total Revenue</div>
        <div class="kpi-value large">$1,275,308</div>
        <div class="kpi-badge">+1.7% YoY</div>
        <div class="kpi-sub">2023: $632,219 · 2024: $643,089</div>
      </div>
      <div class="kpi-card">
        <div class="kpi-label">Total Profit</div>
        <div class="kpi-value large">$510,548</div>
        <div class="kpi-badge">+1.6% YoY</div>
        <div class="kpi-sub">2023: $253,290 · 2024: $257,258</div>
      </div>
      <div class="kpi-card">
        <div class="kpi-label">Avg Profit Margin</div>
        <div class="kpi-value">40.0%</div>
        <div class="kpi-badge neutral">Stable</div>
        <div class="kpi-sub">Range: 39.8% – 40.3%</div>
      </div>
      <div class="kpi-card">
        <div class="kpi-label">Avg Order Value</div>
        <div class="kpi-value">$25.51</div>
        <div class="kpi-badge neutral">Per transaction</div>
        <div class="kpi-sub">50,000 total orders</div>
      </div>
      <div class="kpi-card">
        <div class="kpi-label">Discount Utilization</div>
        <div class="kpi-value">37.6%</div>
        <div class="kpi-badge neutral">of transactions</div>
        <div class="kpi-sub">18,774 discounted orders</div>
      </div>
    </div>

    <!-- YoY Strip -->
    <div class="yoy-strip">
      <div class="yoy-card">
        <div class="yoy-label">Revenue Year-over-Year</div>
        <div class="yoy-values">
          <div class="yoy-year"><span>2023</span><strong>$632,219</strong></div>
          <div class="yoy-year"><span>2024</span><strong>$643,089</strong></div>
          <div class="yoy-change">▲ +1.72%</div>
        </div>
      </div>
      <div class="yoy-card">
        <div class="yoy-label">Profit Year-over-Year</div>
        <div class="yoy-values">
          <div class="yoy-year"><span>2023</span><strong>$253,290</strong></div>
          <div class="yoy-year"><span>2024</span><strong>$257,258</strong></div>
          <div class="yoy-change">▲ +1.57%</div>
        </div>
      </div>
